"use client";

import type { SVGProps } from "react";
import { Select as SelectPrimitive } from "@base-ui/react/select";

import { cn } from "@/lib/utils";
import {
  fieldOpen,
  formFieldBase,
  formFieldSingleLine,
  menuItemBase,
  popoverSurface,
  popupMotion,
} from "./_shared";

// Base UI accepts a state function for className; these wrappers merge it with
// cn(), so they take a plain string.
type WithClassName<P> = Omit<P, "className"> & { className?: string };

/** Mallow Select root: one choice from a short list. */
const Select = SelectPrimitive.Root;

/** Groups related options and gives a label something to name. */
const SelectGroup = SelectPrimitive.Group;

/** Shows the chosen option inside the trigger, or the placeholder. */
const SelectValue = SelectPrimitive.Value;

/** Mallow select trigger: the white field every text input uses, with a muted arrow at the end. */
function SelectTrigger({ className, children, ...props }: WithClassName<SelectPrimitive.Trigger.Props>) {
  return (
    <SelectPrimitive.Trigger
      data-slot="select-trigger"
      className={cn(
        formFieldBase,
        formFieldSingleLine,
        "cursor-default items-center justify-between gap-2 whitespace-nowrap text-start",
        "data-[placeholder]:text-muted-foreground",
        fieldOpen,
        "[&>span]:line-clamp-1",
        className,
      )}
      {...props}
    >
      {children}
      <SelectPrimitive.Icon className="flex shrink-0 text-muted-foreground">
        <ChevronDownIcon className="size-4" aria-hidden="true" />
      </SelectPrimitive.Icon>
    </SelectPrimitive.Trigger>
  );
}
SelectTrigger.displayName = "SelectTrigger";

/** Mallow select list: a floating panel at least as wide as its trigger. */
function SelectContent({
  className,
  children,
  side,
  sideOffset = 8,
  align = "start",
  alignOffset,
  alignItemWithTrigger = false,
  ...props
}: WithClassName<SelectPrimitive.Popup.Props> &
  Pick<SelectPrimitive.Positioner.Props, "side" | "sideOffset" | "align" | "alignOffset" | "alignItemWithTrigger">) {
  return (
    <SelectPrimitive.Portal>
      <SelectPrimitive.Positioner
        className="isolate z-50 outline-none"
        side={side}
        sideOffset={sideOffset}
        align={align}
        alignOffset={alignOffset}
        alignItemWithTrigger={alignItemWithTrigger}
      >
        <SelectPrimitive.Popup
          data-slot="select-content"
          className={cn(popoverSurface, popupMotion, "relative min-w-(--anchor-width) overflow-hidden", className)}
          {...props}
        >
          <SelectPrimitive.ScrollUpArrow className="absolute inset-x-0 top-0 z-10 flex h-6 cursor-default items-center justify-center rounded-t-lg bg-popover text-muted-foreground">
            <ChevronUpIcon className="size-4" aria-hidden="true" />
          </SelectPrimitive.ScrollUpArrow>
          <SelectPrimitive.List
            data-slot="select-list"
            className={cn("p-1.5", !alignItemWithTrigger && "max-h-(--available-height) scroll-py-1.5 overflow-y-auto")}
          >
            {children}
          </SelectPrimitive.List>
          <SelectPrimitive.ScrollDownArrow className="absolute inset-x-0 bottom-0 z-10 flex h-6 cursor-default items-center justify-center rounded-b-lg bg-popover text-muted-foreground">
            <ChevronDownIcon className="size-4" aria-hidden="true" />
          </SelectPrimitive.ScrollDownArrow>
        </SelectPrimitive.Popup>
      </SelectPrimitive.Positioner>
    </SelectPrimitive.Portal>
  );
}
SelectContent.displayName = "SelectContent";

/** A small muted heading over a group of options, used inside a group. */
function SelectLabel({ className, ...props }: WithClassName<SelectPrimitive.GroupLabel.Props>) {
  return (
    <SelectPrimitive.GroupLabel
      data-slot="select-label"
      className={cn("px-2.5 py-1.5 text-xs font-medium text-muted-foreground", className)}
      {...props}
    />
  );
}
SelectLabel.displayName = "SelectLabel";

/** An option row that takes the hover tone when highlighted, with a check at the end once chosen. */
function SelectItem({ className, children, ...props }: WithClassName<SelectPrimitive.Item.Props>) {
  return (
    <SelectPrimitive.Item
      data-slot="select-item"
      className={cn(menuItemBase, "w-full pe-8 data-[selected]:font-medium", className)}
      {...props}
    >
      <SelectPrimitive.ItemText className="line-clamp-1">{children}</SelectPrimitive.ItemText>
      <SelectPrimitive.ItemIndicator className="pointer-events-none absolute end-2 flex size-4 items-center justify-center text-foreground">
        <CheckIcon className="size-4" aria-hidden="true" />
      </SelectPrimitive.ItemIndicator>
    </SelectPrimitive.Item>
  );
}
SelectItem.displayName = "SelectItem";

/** A faint hairline between option groups that runs to the panel's edges. */
function SelectSeparator({ className, ...props }: WithClassName<SelectPrimitive.Separator.Props>) {
  return (
    <SelectPrimitive.Separator
      data-slot="select-separator"
      className={cn("-mx-1.5 my-1.5 h-px bg-border", className)}
      {...props}
    />
  );
}
SelectSeparator.displayName = "SelectSeparator";

export {
  Select,
  SelectGroup,
  SelectValue,
  SelectTrigger,
  SelectContent,
  SelectLabel,
  SelectItem,
  SelectSeparator,
};

// Iconoir, the icon library this system pairs with, drawn inline
// so the installed component loads no icon at runtime:
// "iconoir:check" "iconoir:nav-arrow-down" "iconoir:nav-arrow-up"
// [BD-1029]
function CheckIcon(props: SVGProps<SVGSVGElement>) {
  return (
    <svg xmlns="http://www.w3.org/2000/svg" width="1em" height="1em" viewBox="0 0 24 24" aria-hidden="true" {...props}>
      <path fill="none" stroke="currentColor" strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5" d="m5 13l4 4L19 7"/>
    </svg>
  );
}
function ChevronDownIcon(props: SVGProps<SVGSVGElement>) {
  return (
    <svg xmlns="http://www.w3.org/2000/svg" width="1em" height="1em" viewBox="0 0 24 24" aria-hidden="true" {...props}>
      <path fill="none" stroke="currentColor" strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5" d="m6 9l6 6l6-6"/>
    </svg>
  );
}
function ChevronUpIcon(props: SVGProps<SVGSVGElement>) {
  return (
    <svg xmlns="http://www.w3.org/2000/svg" width="1em" height="1em" viewBox="0 0 24 24" aria-hidden="true" {...props}>
      <path fill="none" stroke="currentColor" strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5" d="m6 15l6-6l6 6"/>
    </svg>
  );
}
